        | OperationResult.Counted(f_count) -> Wire.ofObject [ Some("kind", Wire.ofString "Counted"); Some("count", Wire.ofInt f_count) ]
        | OperationResult.RangeDeleted -> Wire.ofObject [ Some("kind", Wire.ofString "RangeDeleted") ]

    and encodeAbortReason (value: AbortReason) : JsonNode =
        match value with
        | AbortReason.Conflict -> Wire.ofString "conflict"
        | AbortReason.Constraint -> Wire.ofString "constraint"
        | AbortReason.InvalidKey -> Wire.ofString "invalidKey"
        | AbortReason.Quota -> Wire.ofString "quota"
        | AbortReason.UnknownStore -> Wire.ofString "unknownStore"
        | AbortReason.Other -> Wire.ofString "other"

    and encodeStoreRequest (value: StoreRequest) : JsonNode =
        match value with
        | StoreRequest.Open(f_database, f_version, f_stores, f_dropStores) -> Wire.ofObject [ Some("operation", Wire.ofString "open"); Some("database", Wire.ofString f_database); Some("version", Wire.ofInt f_version); Some("stores", (Wire.ofList encodeStoreSchema) f_stores); Some("dropStores", (Wire.ofList Wire.ofString) f_dropStores) ]
        | StoreRequest.Transact(f_database, f_mode, f_operations) -> Wire.ofObject [ Some("operation", Wire.ofString "transact"); Some("database", Wire.ofString f_database); Some("mode", encodeTransactionMode f_mode); Some("operations", (Wire.ofList encodeOperation) f_operations) ]
        | StoreRequest.Close(f_database) -> Wire.ofObject [ Some("operation", Wire.ofString "close"); Some("database", Wire.ofString f_database) ]
        | StoreRequest.DeleteDatabase(f_database) -> Wire.ofObject [ Some("operation", Wire.ofString "deleteDatabase"); Some("database", Wire.ofString f_database) ]

    and encodeStoreResult (value: StoreResult) : JsonNode =
        match value with
        | StoreResult.Opened(f_version, f_upgradedFrom, f_limits) -> Wire.ofObject [ Some("kind", Wire.ofString "Opened"); Some("version", Wire.ofInt f_version); Some("upgradedFrom", Wire.ofInt f_upgradedFrom); f_limits |> Option.map (fun value -> "limits", encodeStoreLimits value) ]
        | StoreResult.VersionConflict(f_stored) -> Wire.ofObject [ Some("kind", Wire.ofString "VersionConflict"); Some("stored", Wire.ofInt f_stored) ]
        | StoreResult.SchemaMismatch(f_problems) -> Wire.ofObject [ Some("kind", Wire.ofString "SchemaMismatch"); Some("problems", (Wire.ofList Wire.ofString) f_problems) ]
        | StoreResult.Blocked -> Wire.ofObject [ Some("kind", Wire.ofString "Blocked") ]
        | StoreResult.Committed(f_results) -> Wire.ofObject [ Some("kind", Wire.ofString "Committed"); Some("results", (Wire.ofList encodeOperationResult) f_results) ]
        | StoreResult.Aborted(f_reason, f_operation, f_current) -> Wire.ofObject [ Some("kind", Wire.ofString "Aborted"); Some("reason", encodeAbortReason f_reason); f_operation |> Option.map (fun value -> "operation", Wire.ofInt value); f_current |> Option.map (fun value -> "current", Wire.ofJson value) ]
        | StoreResult.NotOpen -> Wire.ofObject [ Some("kind", Wire.ofString "NotOpen") ]
        | StoreResult.Closed -> Wire.ofObject [ Some("kind", Wire.ofString "Closed") ]
        | StoreResult.DatabaseDeleted -> Wire.ofObject [ Some("kind", Wire.ofString "DatabaseDeleted") ]
        | StoreResult.InvalidRequest(f_problem) -> Wire.ofObject [ Some("kind", Wire.ofString "InvalidRequest"); Some("problem", Wire.ofString f_problem) ]
        | StoreResult.Unavailable(f_reason) -> Wire.ofObject [ Some("kind", Wire.ofString "Unavailable"); Some("reason", Wire.ofString f_reason) ]
        | StoreResult.Cancelled -> Wire.ofObject [ Some("kind", Wire.ofString "Cancelled") ]

    and encodeStoreFact (value: StoreFact) : JsonNode =
        match value with
        | StoreFact.VersionChanged(f_database, f_newVersion) -> Wire.ofObject [ Some("kind", Wire.ofString "VersionChanged"); Some("database", Wire.ofString f_database); Some("newVersion", Wire.ofInt f_newVersion) ]

    /// The wire text of a TransactionMode value.
    let wireTransactionMode (value: TransactionMode) : string =
        match value with
        | TransactionMode.Readonly -> "readonly"
        | TransactionMode.Readwrite -> "readwrite"

    /// The wire text of a AbortReason value.
    let wireAbortReason (value: AbortReason) : string =
        match value with
        | AbortReason.Conflict -> "conflict"
        | AbortReason.Constraint -> "constraint"
        | AbortReason.InvalidKey -> "invalidKey"
        | AbortReason.Quota -> "quota"
        | AbortReason.UnknownStore -> "unknownStore"
        | AbortReason.Other -> "other"

    let parseIndexSchema (json: string) = Wire.parse decodeIndexSchema json
    let serializeIndexSchema (value: IndexSchema) = (encodeIndexSchema value).ToJsonString()
    let parseStoreSchema (json: string) = Wire.parse decodeStoreSchema json
    let serializeStoreSchema (value: StoreSchema) = (encodeStoreSchema value).ToJsonString()
    let parseStoreLimits (json: string) = Wire.parse decodeStoreLimits json
    let serializeStoreLimits (value: StoreLimits) = (encodeStoreLimits value).ToJsonString()
    let parseTransactionMode (json: string) = Wire.parse decodeTransactionMode json
    let serializeTransactionMode (value: TransactionMode) = (encodeTransactionMode value).ToJsonString()
    let parseKeyRange (json: string) = Wire.parse decodeKeyRange json
    let serializeKeyRange (value: KeyRange) = (encodeKeyRange value).ToJsonString()
    let parseOperation (json: string) = Wire.parse decodeOperation json
    let serializeOperation (value: Operation) = (encodeOperation value).ToJsonString()
    let parseOperationResult (json: string) = Wire.parse decodeOperationResult json
    let serializeOperationResult (value: OperationResult) = (encodeOperationResult value).ToJsonString()
    let parseAbortReason (json: string) = Wire.parse decodeAbortReason json
    let serializeAbortReason (value: AbortReason) = (encodeAbortReason value).ToJsonString()
    let parseStoreRequest (json: string) = Wire.parse decodeStoreRequest json
    let serializeStoreRequest (value: StoreRequest) = (encodeStoreRequest value).ToJsonString()
    let parseStoreResult (json: string) = Wire.parse decodeStoreResult json
    let serializeStoreResult (value: StoreResult) = (encodeStoreResult value).ToJsonString()
    let parseStoreFact (json: string) = Wire.parse decodeStoreFact json
    let serializeStoreFact (value: StoreFact) = (encodeStoreFact value).ToJsonString()

/// Decode-then-encode by type name. Used only by the shared conformance runner.
[<RequireQualifiedAccess>]
module Conformance =
    let roundTrips : Map<string, string -> JsonElement -> Result<JsonNode, DecodeError>> =
        Map.ofList [
            "IndexSchema", (fun path element -> Codec.decodeIndexSchema path element |> Result.map Codec.encodeIndexSchema)
            "StoreSchema", (fun path element -> Codec.decodeStoreSchema path element |> Result.map Codec.encodeStoreSchema)
            "StoreLimits", (fun path element -> Codec.decodeStoreLimits path element |> Result.map Codec.encodeStoreLimits)
            "TransactionMode", (fun path element -> Codec.decodeTransactionMode path element |> Result.map Codec.encodeTransactionMode)
            "KeyRange", (fun path element -> Codec.decodeKeyRange path element |> Result.map Codec.encodeKeyRange)
            "Operation", (fun path element -> Codec.decodeOperation path element |> Result.map Codec.encodeOperation)
            "OperationResult", (fun path element -> Codec.decodeOperationResult path element |> Result.map Codec.encodeOperationResult)
            "AbortReason", (fun path element -> Codec.decodeAbortReason path element |> Result.map Codec.encodeAbortReason)
            "StoreRequest", (fun path element -> Codec.decodeStoreRequest path element |> Result.map Codec.encodeStoreRequest)
            "StoreResult", (fun path element -> Codec.decodeStoreResult path element |> Result.map Codec.encodeStoreResult)
            "StoreFact", (fun path element -> Codec.decodeStoreFact path element |> Result.map Codec.encodeStoreFact)
        ]
